Span<nint> span = stackalloc nint[4];
span[0] = 10;
span[1] = 20;
span[2] = 30;
span[3] = nint.MaxValue;

Console.WriteLine($"Length: {span.Length}");
for (int i = 0; i < span.Length; i++)
    Console.WriteLine($"  span[{i}] = {span[i]}");

Console.WriteLine($"nint size: {sizeof(nint)} bytes");
Console.WriteLine($"nuint max: {nuint.MaxValue}");

// Also test nuint
Span<nuint> uspan = stackalloc nuint[2];
uspan[0] = 42;
uspan[1] = nuint.MaxValue;
Console.WriteLine($"uspan[0] = {uspan[0]}, uspan[1] = {uspan[1]}");

